<?php
defined('PREVENT_DIRECT_ACCESS') or exit('No direct script access allowed');
$e = static fn($value) => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$base = rtrim((string) $app_url, '/') . '/';
$rawTab = $_GET['tab'] ?? '';
$tab = is_scalar($rawTab) && isset($rawTab) && $rawTab !== '' ? (string) $rawTab : 'overview';
$tabs = ['overview' => 'Overview', 'trainees' => 'Trainees', 'schedule' => 'Schedule', 'attendance' => 'Attendance', 'assessments' => 'Assessments', 'documents' => 'Documents', 'announcements' => 'Announcements'];
$rate = static fn($row) => (int) ($row['attendance_total'] ?? 0) > 0 ? round(((int) $row['attendance_attended'] / (int) $row['attendance_total']) * 100, 1) . '%' : '—';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $e($title) ?> | LSI SmartTrack</title><link rel="stylesheet" href="<?= $e($base) ?>assets/css/smarttrack.css?v=<?= (int) filemtime(dirname(__DIR__, 2) . '/public/assets/css/smarttrack.css') ?>"><style>.class-hero{display:flex;justify-content:space-between;gap:20px;align-items:start}.class-tabs{display:flex;gap:4px;overflow-x:auto;margin:18px 0}.class-tabs a{white-space:nowrap;padding:10px 14px;border-radius:7px;color:#265f94}.class-tabs a.active{background:#265f94;color:#fff}.detail-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.detail-stat{padding:16px;border:1px solid #dfe7f1;border-radius:9px;background:#f4f8fd}.detail-stat strong,.detail-stat span{display:block}.detail-stat strong{font-size:24px;color:#173a60}.detail-stat span{color:#596579;font-size:12px}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse}th{background:#eaf1fb;color:#173a60;font-size:11px;text-align:left}th,td{padding:11px;border-bottom:1px solid #e1e8f1;vertical-align:top}.action-row{display:flex;flex-wrap:wrap;gap:8px}.empty-state{padding:35px;text-align:center}@media(max-width:650px){.class-hero{display:grid}}
</style></head><body><div class="portal-shell"><header class="topbar"><a class="wordmark dark" href="<?= $e($base) ?>dashboard">LSI <span>SMARTTRACK</span></a><div class="account-chip"><span class="avatar"><?= $e(strtoupper(substr($user['full_name'] ?? 'U', 0, 1))) ?></span><div><?= $e($user['full_name'] ?? '') ?><small><?= $e(ucfirst($user['role'] ?? '')) ?></small></div><a class="text-button" href="<?= $e($base) ?>manage/classes">My classes</a></div></header><div class="portal-body"><nav class="section-nav" aria-label="Main navigation"><?php foreach ($navigation as $item): ?><a href="<?= $e($base . ($item === 'dashboard' ? 'dashboard' : 'manage/' . $item)) ?>" class="<?= $item === 'classes' ? 'active' : '' ?>"><span class="nav-mark"></span><?= $e($item === 'classes' && $user['role'] === 'instructor' ? 'My classes' : ucfirst($item)) ?></a><?php endforeach; ?></nav><main class="workspace"><section class="panel class-hero"><div><p class="eyebrow">SMARTTRACK / CLASS</p><h1><?= $e($class['class_name']) ?></h1><p class="muted"><?= $e($class['program_name']) ?> · <?= $e($class['start_date'] ?: '—') ?> to <?= $e($class['end_date'] ?: '—') ?></p></div><div class="action-row"><a class="button secondary" href="<?= $e($base) ?>manage/attendance?class_id=<?= $e($class['class_id']) ?>">Take attendance</a><a class="button primary" href="<?= $e($base) ?>manage/assessments?class_id=<?= $e($class['class_id']) ?>">Record assessment</a></div></section><nav class="class-tabs" aria-label="Class detail tabs"><?php foreach ($tabs as $key => $label): ?><a class="<?= $tab === $key ? 'active' : '' ?>" href="?tab=<?= $e($key) ?>"><?= $e($label) ?></a><?php endforeach; ?></nav><?php if ($tab === 'overview'): ?><section class="detail-grid"><div class="detail-stat"><strong><?= $e($stats['attendance_rate']) ?>%</strong><span>Attendance rate</span></div><div class="detail-stat"><strong><?= $e($stats['assessments_passed']) ?></strong><span>Assessments passed</span></div><div class="detail-stat"><strong><?= $e($stats['pending_documents']) ?></strong><span>Pending documents</span></div><div class="detail-stat"><strong><?= $e(count($roster)) ?></strong><span>Enrolled trainees</span></div></section><section class="panel" style="margin-top:18px"><h2>Class information</h2><p><strong>Program:</strong> <?= $e($class['program_name']) ?></p><p><strong>Room:</strong> <?= $e($class['room'] ?: 'Not assigned') ?></p><p><strong>Instructor account:</strong> <?= $e($class['instructor_id']) ?></p></section><?php elseif ($tab === 'trainees'): ?><section class="panel"><h2>Trainee roster</h2><div class="table-scroll"><table><thead><tr><th>Name</th><th>Trainee number</th><th>Attendance</th><th>Pass</th><th>Fail</th><th>Profile</th></tr></thead><tbody><?php foreach ($roster as $row): ?><tr><td><?= $e($row['first_name'] . ' ' . $row['last_name']) ?></td><td><?= $e($row['trainee_number']) ?></td><td><?= $e($rate($row)) ?></td><td><?= $e($row['assessments_passed']) ?></td><td><?= $e($row['assessments_failed']) ?></td><td><a class="text-button" href="<?= $e($base) ?>manage/trainees?search=<?= urlencode($row['last_name']) ?>">View trainee</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php elseif ($tab === 'schedule'): ?><section class="panel"><h2>Class sessions</h2><div class="table-scroll"><table><thead><tr><th>Date</th><th>Start</th><th>End</th></tr></thead><tbody><?php foreach ($schedules as $row): ?><tr><td><?= $e($row['schedule_date']) ?></td><td><?= $e($row['start_time']) ?></td><td><?= $e($row['end_time']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php elseif ($tab === 'attendance'): ?><section class="panel"><h2>Attendance: today and last 7 days</h2><div class="table-scroll"><table><thead><tr><th>Date</th><th>Trainee</th><th>Status</th><th>Time in</th><th>Time out</th></tr></thead><tbody><?php foreach ($attendance as $row): ?><tr><td><?= $e($row['attendance_date']) ?></td><td><?= $e($row['trainee_name']) ?></td><td><?= $e($row['status']) ?></td><td><?= $e($row['time_in']) ?></td><td><?= $e($row['time_out']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php elseif ($tab === 'assessments'): ?><section class="panel"><div class="panel-heading"><h2>Assessment results</h2><a class="button primary" href="<?= $e($base) ?>manage/assessments?class_id=<?= $e($class['class_id']) ?>">Add result</a></div><div class="table-scroll"><table><thead><tr><th>Trainee</th><th>Assessment</th><th>Outcome</th><th>Date</th><th>Notes</th></tr></thead><tbody><?php foreach ($assessments as $row): ?><tr><td><?= $e($row['trainee_name']) ?></td><td><?= $e($row['assessment_name']) ?></td><td><?= $e(ucfirst($row['outcome'])) ?></td><td><?= $e($row['assessment_date']) ?></td><td><?= $e($row['notes']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php elseif ($tab === 'documents'): ?><section class="panel"><div class="panel-heading"><h2>Class documents</h2><a class="button primary" href="<?= $e($base) ?>manage/documents?class_id=<?= $e($class['class_id']) ?>">Upload document</a></div><div class="table-scroll"><table><thead><tr><th>Trainee</th><th>Document</th><th>Uploaded</th><th>Review</th></tr></thead><tbody><?php foreach ($documents as $row): ?><tr><td><?= $e($row['trainee_name'] ?: 'Institution') ?></td><td><?= $e($row['document_name']) ?></td><td><?= $e($row['upload_date']) ?></td><td><?= $e($row['review_status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php else: ?><section class="panel"><div class="panel-heading"><h2>Announcements</h2><a class="button primary" href="<?= $e($base) ?>manage/announcements?class_id=<?= $e($class['class_id']) ?>">Post announcement</a></div><?php foreach ($announcements as $row): ?><article><h3><?= $e($row['title']) ?></h3><p><?= nl2br($e($row['content'])) ?></p><small><?= $e($row['created_at']) ?> · <?= $e($row['author']) ?></small></article><?php endforeach; ?></section><?php endif; ?></main></div></div></body></html>
